import json
import os
import uuid
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.error import HTTPError, URLError
from urllib.parse import urlencode, urlsplit
from urllib.request import Request, urlopen


class DependencyFailure(Exception):
    def __init__(self, stage, status):
        super().__init__(f"{stage} returned HTTP {status}")
        self.stage = stage
        self.status = status


def fetch_json(request, stage):
    try:
        with urlopen(request, timeout=5) as response:
            return json.load(response)
    except HTTPError as error:
        status = error.code
        error.close()
        raise DependencyFailure(stage, status) from None
    except (URLError, TimeoutError, json.JSONDecodeError):
        raise DependencyFailure(stage, 503) from None


def check_secret(environ):
    endpoint = environ["IDENTITY_ENDPOINT"]
    query = urlencode({
        "resource": environ["VAULT_RESOURCE"],
        "api-version": "2019-08-01",
        "client_id": environ["AZURE_CLIENT_ID"],
    })
    separator = "&" if "?" in endpoint else "?"
    token = fetch_json(Request(
        endpoint + separator + query,
        headers={"X-IDENTITY-HEADER": environ["IDENTITY_HEADER"]},
    ), "identity")
    if not isinstance(token, dict) or not isinstance(token.get("access_token"), str):
        raise DependencyFailure("identity", 502)
    if not token["access_token"]:
        raise DependencyFailure("identity", 502)
    vault_url = environ["VAULT_URL"].rstrip("/")
    secret = fetch_json(Request(
        vault_url + "/secrets/training-marker?api-version=7.4",
        headers={"Authorization": "Bearer " + token["access_token"]},
    ), "secret-read")
    if not isinstance(secret, dict) or not isinstance(secret.get("value"), str):
        raise DependencyFailure("secret-read", 502)


def emit(event, **fields):
    print(json.dumps({"event": event, **fields}), flush=True)


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        path = urlsplit(self.path).path
        request_id = str(uuid.uuid4())
        payload = {
            "lab": os.environ["LAB_NUMBER"],
            "status": "ok",
            "requestId": request_id,
        }
        status = 200
        if path not in ("/", "/health", "/check"):
            status, payload["status"] = 404, "not-found"
        elif path == "/check" and os.environ.get("LAB_MODE") == "identity":
            try:
                check_secret(os.environ)
            except DependencyFailure as error:
                status = error.status
                payload["status"] = "dependency-error"
                payload["dependencyStatus"] = error.status
                emit("dependency-error", requestId=request_id,
                     stage=error.stage, status=error.status)
            except KeyError:
                status, payload["status"] = 500, "configuration-error"
                emit("configuration-error", requestId=request_id)
        if "RELEASE" in os.environ:
            payload["release"] = os.environ["RELEASE"]
        emit("request", lab=os.environ["LAB_NUMBER"], requestId=request_id, status=status)
        data = json.dumps(payload).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(data)

    def log_message(self, format, *args):
        # Structured events above replace URL/header logging.
        pass


if __name__ == "__main__":
    port = int(os.environ.get("PORT", "8080"))
    emit("started", lab=os.environ["LAB_NUMBER"], port=port)
    ThreadingHTTPServer(("0.0.0.0", port), Handler).serve_forever()
